//! 🧩️ Fixed authored facets retain their original payload while a paid typed value feeds the scalar row pipeline.
use super::*;
use crate::leaf::RowFieldPreparation;
/// 🧬️ A facet supplies its real typed value and validity from bounded original fixed fields.
pub trait OriginalScalarTransform:ScalarRowPath{type Payload:Send+Sync+'static;fn value(payload:&Self::Payload)->Self::Scalar;fn valid_payload(payload:&Self::Payload)->bool;}
/// 🧳️ Original input, transformed value and scalar preparation remain live until funded closure.
pub struct TransformedScalarPreparation<S:OriginalScalarTransform>{body:Option<usize>,input:Option<RetainedCloneBinding>,source:ManuallyDrop<Option<RetainedCloneSource<S::Scalar>>>,core:Option<Box<ScalarRowPreparation<S>>>,phase:u8,closing:bool}
impl<S:OriginalScalarTransform> TransformedScalarPreparation<S>{fn source(&self)->Result<RetainedCloneRef<'_,S::Scalar>,ValueError>{Ok(self.source.as_ref().ok_or_else(invalid)?.borrow())}fn core(&self)->Result<&ScalarRowPreparation<S>,ValueError>{self.core.as_deref().ok_or_else(invalid)}fn core_mut(&mut self)->Result<&mut ScalarRowPreparation<S>,ValueError>{self.core.as_deref_mut().ok_or_else(invalid)}}
impl<S:OriginalScalarTransform> RowFieldPreparation for TransformedScalarPreparation<S>{
 type Input=S::Payload;type Inverse=S::Scalar;
 fn new()->Self{Self{body:None,input:None,source:ManuallyDrop::new(None),core:None,phase:0,closing:false}}
 fn check(&self,p:RetainedCloneRef<'_,Self::Input>,key:Option<RetainedCloneRef<'_,u32>>,o:RetainedCloneRef<'_,EnergyModelSnapshot>)->Result<(),ValueError>{p.check_binding(&self.input)?;if let Some(core)=self.core.as_ref(){core.check(self.source()?,key.ok_or_else(invalid)?,o)?;}Ok(())}
 fn demand(&self,p:RetainedCloneRef<'_,Self::Input>,key:Option<RetainedCloneRef<'_,u32>>,o:RetainedCloneRef<'_,EnergyModelSnapshot>,body:usize)->Result<RetirementDemand,ValueError>{if self.closing||self.body.is_some_and(|v|v!=body){return Err(invalid());}self.check(p,key,o)?;match self.phase{0=>nested(scalar(p.binding_copy_bytes()+size_of::<usize>()),1),1=>{let d=RetainedCloneSource::<S::Scalar>::owned_constructor_demand::<()>();Ok(RetirementDemand{copy_bytes:2*size_of::<S::Payload>()+RetainedCloneSource::<S::Scalar>::constructor_copy_bytes()+2*size_of::<Option<RetainedCloneSource<S::Scalar>>>()+1,capacity_bytes:d.capacity_bytes,depth:d.depth,..Default::default()})},2=>{let mut d=birth::<ScalarRowPreparation<S>>();d.copy_bytes+=2*size_of::<S::Payload>();Ok(d)},3=>self.core()?.demand(self.source()?,key.ok_or_else(invalid)?,o,body),_=>Err(invalid())}}
 fn advance(&mut self,p:RetainedCloneRef<'_,Self::Input>,key:Option<RetainedCloneRef<'_,u32>>,o:RetainedCloneRef<'_,EnergyModelSnapshot>,body:usize,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=self.demand(p,key,o,body)?;if !retained_mutation_demand_fits(d,g){return Ok(RetainedCloneStep::Progress(Default::default()));}let mut progress=receipt(d);self.body=Some(body);match self.phase{0=>{progress=add(p.bind(&mut self.input,child(g,1+size_of::<usize>()))?.ok_or_else(invalid)?,1+size_of::<usize>())?;self.phase=1;},1=>{let extra=2*size_of::<S::Payload>()+2*size_of::<Option<RetainedCloneSource<S::Scalar>>>()+1;let value=S::value(p.get());let(source,p)=RetainedCloneSource::admit_owned(value,(),RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes-extra,..g}).map_err(|(e,_,())|tag(e,extra))?;*self.source=Some(source);self.phase=2;progress=add(p,extra)?;},2=>{self.core=Some(Box::new(ScalarRowPreparation::with_authored_validation(S::valid_payload(p.get()))));self.phase=3;},3=>{let source=self.source.as_ref().ok_or_else(invalid)?.borrow();return self.core.as_mut().ok_or_else(invalid)?.advance(source,key.ok_or_else(invalid)?,o,body,g);},_=>return Err(invalid())}semio_framework_value::retained_clone::admit_retained_clone_progress(g,progress,"original fixed Energy facet")?;Ok(RetainedCloneStep::Progress(progress))}
 fn ready(&self)->bool{!self.closing&&self.core.as_ref().is_some_and(|c|c.ready())}fn outcome(&self)->Option<ScalarOutcome>{self.core.as_ref().and_then(|c|c.outcome())}
 fn take_demand(&self)->Result<RetirementDemand,ValueError>{self.core()?.take_demand()}fn take(&mut self,g:RetainedCloneGrant)->Result<Option<(EnergyModelDiff,RetainedCloneProgress)>,ValueError>{self.core_mut()?.take(g)}
 fn inverse_demand(&self,b:usize)->Result<RetirementDemand,ValueError>{RowFieldPreparation::inverse_demand(self.core()?,b)}fn prepare_inverse(&mut self,b:usize,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{RowFieldPreparation::prepare_inverse(self.core_mut()?,b,g)}fn inverse_ready(&self)->bool{self.core.as_ref().is_some_and(|c|RowFieldPreparation::inverse_ready(&**c))}fn take_inverse_demand(&self)->Result<RetirementDemand,ValueError>{self.core()?.inverse_demand()}fn take_inverse(&mut self,g:RetainedCloneGrant)->Result<Option<(Self::Inverse,RetainedCloneProgress)>,ValueError>{self.core_mut()?.take_inverse(g)}
 fn begin_close(&mut self){self.closing=true;if let Some(c)=self.core.as_mut(){c.begin_close();}}
 fn close_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.closing{return Err(invalid());}let body=self.body.unwrap_or(body);if self.core.is_some(){return cursor_demand(&self.core,body);}if let Some(source)=self.source.as_ref(){return if source.terminal_is_empty(){Ok(scalar(2*size_of::<Option<RetainedCloneSource<S::Scalar>>>()))}else{source.next_close_demand(body)};}RetainedCloneBinding::close_demand(&self.input,body)}
 fn close_step(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=self.close_demand(self.body.unwrap_or(g.maximum_copy_bytes))?;if self.terminal_is_empty(){return Ok(RetainedCloneStep::Complete(Default::default()));}if !retained_mutation_demand_fits(d,g){return Ok(RetainedCloneStep::Progress(Default::default()));}let g=RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes,..g};if self.core.is_some(){return close_cursor(&mut self.core,g).map(RetainedCloneStep::Progress);}if let Some(source)=self.source.as_mut(){if source.terminal_is_empty(){drop(self.source.take());return Ok(RetainedCloneStep::Progress(receipt(d)));}return source.close_step(g).map(|s|RetainedCloneStep::Progress(s.progress()));}let p=RetainedCloneBinding::close_one(&mut self.input,g)?.progress();Ok(if self.terminal_is_empty(){RetainedCloneStep::Complete(p)}else{RetainedCloneStep::Progress(p)})}
 fn terminal_is_empty(&self)->bool{self.closing&&self.core.is_none()&&self.source.is_none()&&self.input.is_none()}
}
impl<S:OriginalScalarTransform> Drop for TransformedScalarPreparation<S>{fn drop(&mut self){let empty=self.terminal_is_empty();assert!(std::thread::panicking()||empty,"original fixed Energy facet retains source or scalar preparation");if empty{unsafe{ManuallyDrop::drop(&mut self.source);}}}}
impl<S:ScalarRowPath> CursorClose for ScalarRowPreparation<S>{fn close_demand(&self,b:usize)->Result<RetirementDemand,ValueError>{Self::close_demand(self,b)}fn close_step(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{Self::close_step(self,g)}fn terminal_is_empty(&self)->bool{Self::terminal_is_empty(self)}}
